{
  "propositions": [
    {
      "text": "Regulation (EU) 2024/1689 is also known as the Artificial Intelligence Act.",
      "exactQuote": "Regulation (EU) 2024/1689 — Artificial Intelligence Act",
      "blockId": "c-law-001#block-0"
    },
    {
      "text": "The AI Act was adopted on 13 June 2024.",
      "exactQuote": "Adopted: 13 June 2024",
      "blockId": "c-law-001#block-3"
    },
    {
      "text": "The AI Act entered into force on 2 August 2024.",
      "exactQuote": "Entered into force: 2 August 2024",
      "blockId": "c-law-001#block-3"
    },
    {
      "text": "The AI Act was published in the Official Journal L series on 12 July 2024.",
      "exactQuote": "Published in OJ: L series, 12 July 2024",
      "blockId": "c-law-001#block-3"
    },
    {
      "text": "The AI Act is also known as the 'AI Act' or 'EU AI Act'.",
      "exactQuote": "Also known as: \"AI Act\", \"EU AI Act\"",
      "blockId": "c-law-001#block-3"
    },
    {
      "text": "The purpose of the AI Act is to improve the functioning of the internal market by laying down a uniform legal framework for AI systems in the Union.",
      "exactQuote": "The purpose of this Regulation is to improve the functioning of the internal market by laying down a uniform legal framework in particular for the development, the placing on the market, the putting into service and the use of artificial intelligence systems (AI systems) in the Union, in accordance with Union values, to promote the uptake of human centric and trustworthy artificial intelligence (AI) while ensuring a high level of protection of health, safety, fundamental rights as enshrined in the Charter of Fundamental Rights of the European Union (the 'Charter'), including democracy, the rule of law and environmental protection, to protect against the harmful effects of AI systems in the Union, and to support innovation.",
      "blockId": "c-law-001#block-5"
    },
    {
      "text": "The AI Act adopts a four-tier risk classification.",
      "exactQuote": "The AI Act adopts a four-tier risk classification:",
      "blockId": "c-law-001#block-7"
    },
    {
      "text": "Unacceptable risk AI practices are prohibited and include: subliminal techniques causing harm; exploiting vulnerabilities due to age, disability, or social/economic situation; social scoring; predictive policing based on profiling; untargeted scraping of facial images; emotion inference in workplace/education; biometric categorization of sensitive characteristics; real-time remote biometric identification for law enforcement (with narrow exceptions).",
      "exactQuote": "Unacceptable Risk — Prohibited practices include: subliminal techniques causing harm; exploiting vulnerabilities due to age, disability, or social/economic situation; social scoring; predictive policing based on profiling; untargeted scraping of facial images; emotion inference in workplace/education; biometric categorization of sensitive characteristics; real-time remote biometric identification for law enforcement (with narrow exceptions).",
      "blockId": "c-law-001#block-8"
    },
    {
      "text": "High-risk AI systems include those that are safety components of products (Annex I) or fall within eight specific use cases (Annex III).",
      "exactQuote": "High Risk — AI systems that are safety components of products (Annex I) or fall within eight specific use cases (Annex III), including: biometric identification; critical infrastructure management; education and vocational training; employment and worker management; access to essential services; law enforcement; migration and border control; administration of justice and democratic processes.",
      "blockId": "c-law-001#block-8"
    },
    {
      "text": "Specific transparency risk applies to chatbots, deepfakes, and emotion recognition systems, which must disclose their AI nature.",
      "exactQuote": "Specific Transparency Risk — Chatbots, deepfakes, and emotion recognition systems must disclose their AI nature.",
      "blockId": "c-law-001#block-8"
    },
    {
      "text": "Minimal risk applies to most AI systems, with no additional obligations beyond existing law.",
      "exactQuote": "Minimal Risk — Most AI systems; no additional obligations beyond existing law.",
      "blockId": "c-law-001#block-8"
    },
    {
      "text": "For infringements on prohibited practices, penalties are up to €35 million or 7% of total worldwide annual turnover, whichever is higher.",
      "exactQuote": "For infringements on prohibited practices: up to €35 million or 7% of total worldwide annual turnover (whichever is higher).",
      "blockId": "c-law-001#block-10"
    },
    {
      "text": "For other infringements, penalties are up to €15 million or 3% of total worldwide annual turnover.",
      "exactQuote": "For other infringements: up to €15 million or 3%.",
      "blockId": "c-law-001#block-10"
    },
    {
      "text": "Prohibitions on unacceptable risk practices take effect on 2 February 2025.",
      "exactQuote": "2 February 2025: Prohibitions on unacceptable risk practices take effect",
      "blockId": "c-law-001#block-12"
    },
    {
      "text": "Member states must designate competent authorities by 2 August 2025.",
      "exactQuote": "2 August 2025: Member states must designate competent authorities",
      "blockId": "c-law-001#block-12"
    },
    {
      "text": "Rules for high-risk AI systems (Annex III) take effect on 2 August 2026.",
      "exactQuote": "2 August 2026: Rules for high-risk AI systems (Annex III) take effect",
      "blockId": "c-law-001#block-12"
    },
    {
      "text": "Rules for product-linked high-risk AI systems (Annex I) take effect on 2 August 2027.",
      "exactQuote": "2 August 2027: Rules for product-linked high-risk AI systems (Annex I) take effect",
      "blockId": "c-law-001#block-12"
    }
  ]
}
